using System.Net.Http; using System.Net.Http.Json; using System.Text.Json; using System.Windows; using System.Windows.Controls; using System.Windows.Media; namespace CloudClient; public sealed class LoginWindow:Window { readonly TextBox server=new(){Text="http://localhost:5050"},user=new(); readonly PasswordBox pass=new(); readonly TextBlock state=new(){Foreground=Brushes.Gray}; readonly HttpClient http=new(); public LoginWindow(){Title="i-NET-PROMO Cloudservice";Width=520;Height=590;WindowStartupLocation=WindowStartupLocation.CenterScreen;ResizeMode=ResizeMode.NoResize;Background=new SolidColorBrush(Color.FromRgb(246,248,251));var card=new Border{Background=Brushes.White,CornerRadius=new CornerRadius(14),Margin=new Thickness(45),Padding=new Thickness(38)};var s=new StackPanel();s.Children.Add(new TextBlock{Text="i-NET-PROMO",FontSize=30,FontWeight=FontWeights.Bold,Foreground=new SolidColorBrush(Color.FromRgb(20,55,91))});s.Children.Add(new TextBlock{Text="CLOUDSERVICE",FontSize=12,FontWeight=FontWeights.Bold,Foreground=new SolidColorBrush(Color.FromRgb(0,169,201)),Margin=new Thickness(0,0,0,30)});s.Children.Add(new TextBlock{Text="Willkommen zurück",FontSize=23,FontWeight=FontWeights.Bold,Margin=new Thickness(0,0,0,20)});Add(s,"Serveradresse",server);Add(s,"Benutzername",user);Add(s,"Passwort",pass);var b=new Button{Content="Anmelden",Height=44,Margin=new Thickness(0,22,0,12),Background=new SolidColorBrush(Color.FromRgb(0,169,201)),Foreground=Brushes.White,BorderThickness=new Thickness(0)};b.Click+=async(_,__)=>await Login();s.Children.Add(b);s.Children.Add(state);card.Child=s;Content=card;} static void Add(Panel p,string l,Control c){p.Children.Add(new TextBlock{Text=l,Margin=new Thickness(0,8,0,5),Foreground=Brushes.DimGray});c.Height=38;c.FontSize=14;c.Padding=new Thickness(10,5,10,5);p.Children.Add(c);} async Task Login(){try{state.Text="Verbindung wird hergestellt …";var baseUrl=server.Text.TrimEnd('/');var r=await http.PostAsJsonAsync(baseUrl+"/api/login",new{UserName=user.Text,Password=pass.Password});if(!r.IsSuccessStatusCode){state.Text="Anmeldung fehlgeschlagen";return;}var login=await r.Content.ReadFromJsonAsync<LoginResult>();if(login==null||string.IsNullOrWhiteSpace(login.Token)){state.Text="Ungültige Serverantwort";return;}new MainWindow(baseUrl,login.Token).Show();Close();}catch(Exception e){state.Text="Server nicht erreichbar: "+e.Message;}} sealed class LoginResult{public string Token{get;set;}="";} }